@Entity(tableName = "topics")
data class TopicEntity(
    @PrimaryKey val id: String = UUID.randomUUID().toString(),
    val title: String,
    val description: String,
    val masteryLevel: Int = 0,
    val createdAt: Long = System.currentTimeMillis(),
    val lastAccessed: Long = System.currentTimeMillis(),
    val nextLearningGoal: String? = null
)

@Entity(tableName = "messages",
foreignKeys = [ForeignKey(entity = TopicEntity::class, parentColumns = ["id"], childColumns = ["topicId"], onDelete = ForeignKey.CASCADE)])
data class MessageEntity(
    @PrimaryKey val id: String = UUID.randomUUID().toString(),
    val topicId: String,
    val content: String,
    val senderType: String, // USER or AI
    val messageType: String, // TEXT, AUDIO, FILE_CONTENT
    val timestamp: Long = System.currentTimeMillis()
)

@Dao
interface TopicDao {
    @Query("SELECT * FROM topics ORDER BY lastAccessed DESC")
    fun getAllTopics(): Flow<List<TopicEntity>>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertTopic(topic: TopicEntity)

    @Update
    suspend fun updateTopic(topic: TopicEntity)

    @Delete
    suspend fun deleteTopic(topic: TopicEntity)
}

@Dao
interface MessageDao {
    @Query("SELECT * FROM messages WHERE topicId = :topicId ORDER BY timestamp ASC")
    fun getMessagesByTopic(topicId: String): Flow<List<MessageEntity>>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertMessage(message: MessageEntity)

    @Update
    suspend fun updateMessage(message: MessageEntity)
}

@Database(entities = [TopicEntity::class, MessageEntity::class], version = 1)
abstract class AppDatabase : RoomDatabase() {
    abstract fun topicDao(): TopicDao
    abstract fun messageDao(): MessageDao

    companion object {
        @Volatile private var INSTANCE: AppDatabase? = null
        fun getDatabase(context: Context): AppDatabase =
            INSTANCE ?: synchronized(this) {
                Room.databaseBuilder(context, AppDatabase::class.java, "teachitback_db")
                    .fallbackToDestructiveMigration()
                    .build().also { INSTANCE = it }
            }
    }
}

class MessageRepository(private val messageDao: MessageDao) {
    fun getMessagesByTopic(topicId: String): Flow<List<MessageEntity>> = 
        messageDao.getMessagesByTopic(topicId)

    suspend fun insertMessage(message: MessageEntity) = messageDao.insertMessage(message)

    suspend fun updateMessage(message: MessageEntity) = messageDao.updateMessage(message)
}

class AppViewModel(application: Application) : AndroidViewModel(application) {
    private val database = AppDatabase.getDatabase(application)
    private val topicRepository = TopicRepository(database.topicDao())
    private val messageRepository = MessageRepository(database.messageDao())

    val topics: LiveData<List<TopicEntity>> = topicRepository.getAllTopics().asLiveData()

    fun insertTopic(title: String, description: String) = viewModelScope.launch {
        topicRepository.insertTopic(TopicEntity(title = title, description = description))
    }
}

