interface AIService {
    suspend fun sendMessage(messages: List<MessageEntity>, context: String): String
    suspend fun processFileContent(content: String, context: String): String
}

class OpenAIService(private val apiKey: String) : AIService {
    override suspend fun sendMessage(messages: List<MessageEntity>, context: String): String {
        val client = OkHttpClient()
        val requestBody = createChatRequestBody(messages, context)
        val request = Request.Builder()
            .url("https://api.openai.com/v1/chat/completions")
            .post(requestBody)
            .addHeader("Authorization", "Bearer $apiKey")
            .build()

        val response = client.newCall(request).execute()
        return parseResponse(response)
    }
}

class FileProcessor(private val context: Context) {
    fun extractTextFromPdf(uri: Uri): String {
        val inputStream = context.contentResolver.openInputStream(uri)
        val loader = PDFLoader()
        val document = loader.loadDocument(inputStream)
        val stripper = PDFTextStripper()
        return stripper.getText(document)
    }

    fun extractTextFromTextFile(uri: Uri): String {
        val inputStream = context.contentResolver.openInputStream(uri)
        return inputStream.bufferedReader().use { it.readText() }
    }
}

class VoiceProcessor(private val context: Context) {
    private val speechRecognizer = SpeechRecognizer.createSpeechRecognizer(context)

    fun startListening(onResult: (String) -> Unit) {
        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, Locale.getDefault())
        }
        speechRecognizer.setRecognitionListener(object : RecognitionListener {
            override fun onResults(results: Bundle?) {
                val matches = results?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
                onResult(matches?.firstOrNull() ?: "")
            }
            // Other required methods...
        })
        speechRecognizer.startListening(intent)
    }
}

class TopicsAdapter(private val onClick: (TopicEntity) -> Unit) : 
    RecyclerView.Adapter<TopicsAdapter.TopicViewHolder>() {

    private var topics = listOf<TopicEntity>()

    fun submitList(newTopics: List<TopicEntity>) {
        topics = newTopics
        notifyDataSetChanged()
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): TopicViewHolder {
        val binding = ItemTopicBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return TopicViewHolder(binding)
    }

    override fun onBindViewHolder(holder: TopicViewHolder, position: Int) {
        holder.bind(topics[position])
    }

    class TopicViewHolder(private val binding: ItemTopicBinding) : 
        RecyclerView.ViewHolder(binding.root) {
        fun bind(topic: TopicEntity) {
            binding.titleText.text = topic.title
            binding.progressText.text = "Mastery: ${topic.masteryLevel}%"
            binding.root.setOnClickListener { onClick(topic) }
        }
    }
}

class MessagesAdapter : RecyclerView.Adapter<RecyclerView.ViewHolder>() {
    private val VIEW_TYPE_USER = 1
    private val VIEW_TYPE_AI = 2

    private var messages = listOf<MessageEntity>()

    fun submitList(newMessages: List<MessageEntity>) {
        messages = newMessages
        notifyDataSetChanged()
    }

    override fun getItemViewType(position: Int): Int {
        return if (messages[position].senderType == "USER") VIEW_TYPE_USER else VIEW_TYPE_AI
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): RecyclerView.ViewHolder {
        val inflater = LayoutInflater.from(parent.context)
        return if (viewType == VIEW_TYPE_USER) {
            UserMessageViewHolder(ItemUserMessageBinding.inflate(inflater, parent, false))
        } else {
            AIMessageViewHolder(ItemAiMessageBinding.inflate(inflater, parent, false))
        }
    }
}

class MainActivity : AppCompatActivity() {
    private lateinit var binding: ActivityMainBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        setupBottomNavigation()
    }

    private fun setupBottomNavigation() {
        binding.bottomNavigation.setOnItemSelectedListener { item ->
            val fragment = when (item.itemId) {
                R.id.navigation_topics -> TopicsFragment()
                R.id.navigation_why -> WhyFragment()
                R.id.navigation_settings -> SettingsFragment()
                else -> TopicsFragment()
            }
            supportFragmentManager.beginTransaction()
                .replace(R.id.fragment_container, fragment)
                .commit()
            true
        }
    }
}

